/* Presentation fixtures only: no game imports, evaluator, RNG, storage or network calls. */
const asset='../../public/assets/handdrawn-p08/cards/';
const fixtures=[
{id:'mantangcai',name:'满堂彩',rarity:'普通',edition:'普通',editionEffect:'无附加效果',mark:'●',stars:4,word:'很合用',route:'契合成组',combo:'无需搭档',dots:'',hook:'成组就加热度',conditions:[['✓','成组主手 · 样例为葫芦'],['✓','直接加热，不依赖重触发搭档']],note:'卡牌效果：任何成组牌型，整手热度 +90。推荐星数仅用于本页展示。'},
{id:'e08',name:'包场',rarity:'稀有',edition:'全息',editionEffect:'倍率+2',mark:'✦',stars:2,word:'暂缓',route:'各路线通用',combo:'门槛未满足',dots:'○',hook:'购后 18 金 / 需 20 金',conditions:[['○','购后只余 18 金，尚缺 2 金'],['✓','任何路线均可使用']],note:'卡牌效果：当前金币至少 20 时，整手倍率 ×1.8。通用不等于当前适合，稀有度不随金币改变。'},
{id:'b06',name:'再说一遍',rarity:'稀有',edition:'普通',editionEffect:'无附加效果',mark:'✦',stars:3,word:'待搭配',route:'契合成组',combo:'已满足 1/2',dots:'●○',hook:'缺「一束光」搭档',conditions:[['✓','成组主手 · 三张 K 在前'],['○','缺一束光 · 补充逐牌热度来源']],note:'再说一遍让成组主手中最大同点组的有效牌再计一次。一束光可让合格主手的首张有效计分牌再次获得 +15 热度；这里只呈现组合关系，不估算整手收益。'}
];
let complete=false,selecting=false;const selected=new Set();
const star=filled=>`<svg class="${filled?'filled':''}" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.4 14.9 8.6 21.8 9.4 16.7 14.1 18.1 21 12 17.5 5.9 21 7.3 14.1 2.2 9.4 9.1 8.6Z"/></svg>`;
const stars=n=>`<span class="stars" role="img" aria-label="推荐指数 ${n} 星，满分 5 星">${Array.from({length:5},(_,i)=>star(i<n)).join('')}</span>`;
function current(){return fixtures.map(c=>c.id==='b06'&&complete?{...c,stars:5,word:'极佳契合',combo:'已满足 2/2',dots:'●●',hook:'模拟齐备 · 逐牌再计',conditions:[['✓','成组主手 · 三张 K 在前'],['✓','已有一束光 · 首张 K 可再获热度']]}:c);}
function combo(c){const type=c.id==='mantangcai'?'solo':c.id==='e08'?'threshold':complete?'complete':'missing';const label=c.id==='mantangcai'?'无需搭档':c.id==='e08'?'门槛 18 / 20 金':complete?'搭档齐备 · 2/2':'缺搭档 · 1/2';return `<span class="combo-mark ${type}" aria-hidden="true"><i></i>${type==='missing'||type==='complete'?'<i></i>':''}</span><span class="combo-status">${label}</span>`;}
const rating=c=>`<span class="recommend ${c.stars===5?'five':''}"><span class="rating"><span class="rec-label">推荐指数 · 样例</span>${stars(c.stars)}</span><span class="rec-word">${c.stars===5?'<i class="gem" aria-hidden="true"></i>':''}${c.word}</span></span>`;
function render(){const rail=document.querySelector('#cards'),scroll=rail.scrollLeft;rail.innerHTML=current().map(c=>`<button class="card ${selected.has(c.id)?'selected':''}" data-card="${c.id}" aria-label="${selecting?(selected.has(c.id)?'移出对比':'选入对比'):'查看条件'}：${c.name}" ${selecting?`aria-pressed="${selected.has(c.id)}"`:'aria-haspopup="dialog"'}><span class="card-head"><span class="name">${c.name}</span><span class="rarity" aria-label="固有稀有度：${c.rarity}"><b aria-hidden="true">${c.mark}</b>${c.rarity}</span></span><img class="portrait" src="${asset+c.id}.detail.webp" alt="${c.name}原手绘人物" width="256" height="320"><span class="card-foot">${rating(c)}<span class="card-meta"><span class="route-tag">${c.route}</span><span class="edition" aria-label="独立版次：${c.edition}，${c.editionEffect}">${c.edition}版次</span></span><span class="combo">${combo(c)}</span></span></button>`).join('');rail.scrollLeft=scroll;syncRail();updateSelection();}
function updateSelection(message){const action=document.querySelector('#compare');document.querySelector('#cancel-selection').hidden=!selecting;document.querySelector('#mode-hint').textContent=selecting?'点牌选择，再点取消选择':'点牌看条件';action.textContent=selecting?`比较这两张 ${selected.size}/2`:'选择对比';action.disabled=selecting&&selected.size!==2;document.querySelector('#selection-status').textContent=message||(selecting?selected.size===0?'选择两位助演':selected.size===1?'已选一位，再选一位':'已选两位，可以比较':'选两张，一起看');}
const detail=document.querySelector('#detail');function openDetail(c){document.querySelector('#detail-content').innerHTML=`<div class="detail-hero"><img src="${asset+c.id}.detail.webp" alt="${c.name}原手绘人物"><div><h2 id="detail-title">${c.name}</h2><span class="rarity">${c.mark} ${c.rarity}</span><div class="detail-rating ${c.stars===5?'five':''}"><span class="rec-label">推荐指数 · 样例</span>${stars(c.stars)}</div></div></div><div class="detail-dimensions"><span>路线：${c.route}</span><span>${c.id==='e08'?'生效门槛':'组合条件'}：${c.combo}</span><span class="detail-edition">独立版次：${c.edition} · ${c.editionEffect}</span></div><ul class="conditions">${c.conditions.map(([s,t])=>`<li><span class="check">${s}</span><span>${t}</span></li>`).join('')}</ul><p class="detail-note">${c.note}</p><p class="axis-note">推荐星是固定展示评分；组合显示当前条件，齐备不等于已经触发。版次是独立加成，不改变卡牌稀有度，也不规定推荐星数。</p>`;detail.showModal();}
function syncRail(){for(const card of document.querySelectorAll('.card')){const r=card.getBoundingClientRect();card.classList.toggle('peek',innerWidth<=700&&(r.left<0||r.right>innerWidth));}}
document.querySelector('#cards').addEventListener('scroll',syncRail,{passive:true});window.addEventListener('resize',syncRail);
document.querySelector('#cards').addEventListener('click',e=>{const b=e.target.closest('.card');if(!b)return;const id=b.dataset.card;if(!selecting){openDetail(current().find(c=>c.id===id));return;}if(selected.has(id))selected.delete(id);else if(selected.size<2)selected.add(id);else{updateSelection('已选满，请先取消一位');return;}render();document.querySelector(`[data-card="${id}"]`).focus({preventScroll:true});});
document.querySelector('#close-detail').onclick=()=>detail.close();
function changeFixture(value){complete=value;document.querySelector('#missing').setAttribute('aria-pressed',String(!value));document.querySelector('#ready').setAttribute('aria-pressed',String(value));render();updateSelection(value?'齐备展示 · 非实际算分':'缺搭档展示');}
document.querySelector('#missing').onclick=()=>changeFixture(false);document.querySelector('#ready').onclick=()=>changeFixture(true);
const dialog=document.querySelector('#comparison');document.querySelector('#compare').onclick=()=>{if(!selecting){selecting=true;render();return;}document.querySelector('#comparison-content').innerHTML=`<div class="compare-grid">${current().filter(c=>selected.has(c.id)).map(c=>`<section class="compare-column"><img src="${asset+c.id}.detail.webp" alt="${c.name}原手绘人物"><h3>${c.name}</h3><div class="compare-item ${c.stars===5?'five':''}"><small>推荐指数 · 样例</small>${stars(c.stars)}<strong>${c.word}</strong></div><div class="compare-item"><small>固有稀有度</small>${c.mark} ${c.rarity}</div><div class="compare-item"><small>独立版次</small>${c.edition} · ${c.editionEffect}</div><div class="compare-item"><small>路线</small>${c.route}</div><div class="compare-item"><small>${c.id==='e08'?'生效门槛':'组合条件'}</small>${c.combo}<br>${c.hook}</div></section>`).join('')}</div>`;dialog.showModal();};document.querySelector('#close-compare').onclick=()=>dialog.close();document.querySelector('#cancel-selection').onclick=()=>{selecting=false;selected.clear();render();document.querySelector('#compare').focus();};render();
